def choose_move(observation):
    def getd(obj, key, default=None):
        if hasattr(obj, "get"):
            return obj.get(key, default)
        return default

    def as_xy(v):
        if v is None:
            return None
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return [v[0], v[1]]
        if isinstance(v, dict):
            for a, b in (("x", "y"), ("col", "row"), ("i", "j")):
                if a in v and b in v:
                    return [v[a], v[b]]
        return None

    def find_self_pos(obs):
        for k in ("self_pos", "agent_pos", "position", "pos", "loc", "location"):
            p = as_xy(getd(obs, k))
            if p is not None:
                return p
        me = getd(obs, "self")
        p = as_xy(me)
        if p is not None:
            return p
        return [0, 0]

    def extract_xy_list(v):
        out = []
        if v is None:
            return out
        if isinstance(v, dict):
            if "positions" in v:
                return extract_xy_list(v.get("positions"))
            if "items" in v:
                return extract_xy_list(v.get("items"))
            p = as_xy(v)
            return [p] if p is not None else []
        if isinstance(v, (list, tuple)):
            for item in v:
                p = as_xy(item)
                if p is not None:
                    out.append(p)
        return out

    def clamp(n):
        if n < -1:
            return -1
        if n > 1:
            return 1
        return n

    me = find_self_pos(observation)
    x, y = me[0], me[1]

    width = getd(observation, "width", getd(observation, "cols", getd(observation, "grid_width")))
    height = getd(observation, "height", getd(observation, "rows", getd(observation, "grid_height")))

    resources = []
    for key in ("resources", "resource_positions", "targets", "food", "collectibles", "pickups"):
        resources.extend(extract_xy_list(getd(observation, key)))

    enemies = []
    for key in ("enemies", "opponents", "enemy_positions", "others", "units"):
        enemies.extend(extract_xy_list(getd(observation, key)))

    territory = []
    for key in ("territory", "unclaimed", "cells", "frontier", "control_points", "bases"):
        territory.extend(extract_xy_list(getd(observation, key)))

    mode = str(getd(observation, "mode", getd(observation, "task", getd(observation, "scenario", "")))).lower()
    role = str(getd(observation, "role", getd(observation, "agent_type", ""))).lower()

    candidates = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    best_score = None

    for dx, dy in candidates:
        nx = x + dx
        ny = y + dy
        score = 0.0

        if width is not None:
            if nx < 0 or nx >= width:
                score -= 50.0
        if height is not None:
            if ny < 0 or ny >= height:
                score -= 50.0

        if resources:
            dmin = None
            for rx, ry in resources:
                d = abs(rx - nx) + abs(ry - ny)
                if dmin is None or d < dmin:
                    dmin = d
            if dmin is not None:
                score += 12.0 / (1.0 + dmin)

        if territory:
            dmin = None
            for tx, ty in territory:
                d = abs(tx - nx) + abs(ty - ny)
                if dmin is None or d < dmin:
                    dmin = d
            if dmin is not None:
                score += 6.0 / (1.0 + dmin)

        if enemies:
            dmin = None
            for ex, ey in enemies:
                d = abs(ex - nx) + abs(ey - ny)
                if dmin is None or d < dmin:
                    dmin = d
            if dmin is not None:
                if "pursuit" in mode or "hunt" in mode or "chase" in role or "attacker" in role:
                    score += 8.0 / (1.0 + dmin)
                else:
                    score -= 10.0 / (1.0 + dmin)

        if dx == 0 and dy == 0:
            score -= 0.2

        if best_score is None or score > best_score:
            best_score = score
            best = (dx, dy)

    return [clamp(best[0]), clamp(best[1])]

